.sl-faq-accordion { background-color: var(--smartlearn-bg); padding-block: clamp(3rem, 6vw, 5rem); padding-inline: clamp(1rem, 4vw, 2rem); width: 100%; font-family: var(--smartlearn-body-font, system-ui, sans-serif); }
.sl-faq-accordion .sl-container { max-width: 800px; margin-inline: auto; }
.sl-faq-accordion .sl-header { text-align: center; margin-bottom: 3rem; }
.sl-faq-accordion .sl-title { font-family: var(--smartlearn-heading-font, inherit); font-size: clamp(1.85rem, 3.5vw, 2.5rem); font-weight: 800; color: var(--smartlearn-text); margin-bottom: 1rem; }
.sl-faq-accordion .sl-subtitle { font-size: 1.125rem; color: var(--smartlearn-text-muted); margin: 0; }
.sl-faq-accordion .sl-accordion { display: flex; flex-direction: column; gap: 1rem; }
.sl-faq-accordion .sl-item { background: var(--smartlearn-card-bg, transparent); border: 1px solid var(--smartlearn-card-border, rgba(148, 163, 184, 0.25)); border-radius: var(--smartlearn-radius, 8px); overflow: hidden; backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); }
.sl-faq-accordion .sl-q-heading { margin: 0; font-size: inherit; }
.sl-faq-accordion .sl-q-btn { width: 100%; min-height: 44px; display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: 1.25rem 1.5rem; background: transparent; border: none; color: var(--smartlearn-text); font-family: var(--smartlearn-heading-font, inherit); font-size: 1.125rem; font-weight: 600; cursor: pointer; text-align: start; }
.sl-faq-accordion .sl-q-btn::after { content: ''; width: 0.6rem; height: 0.6rem; border-inline-end: 2px solid var(--smartlearn-primary); border-bottom: 2px solid var(--smartlearn-primary); transform: rotate(45deg); transition: transform 0.25s ease; flex-shrink: 0; margin-inline-end: 0.25rem; }
.sl-faq-accordion .sl-item.active .sl-q-btn::after { transform: rotate(-135deg); }
.sl-faq-accordion .sl-q-btn:focus-visible { outline: 3px solid var(--smartlearn-primary); outline-offset: -3px; }
.sl-faq-accordion .sl-a-wrapper { display: grid; grid-template-rows: 0fr; transition: grid-template-rows 0.3s ease; }
.sl-faq-accordion:not([data-sl-init="1"]) .sl-a-wrapper, .sl-faq-accordion .sl-item.active .sl-a-wrapper { grid-template-rows: 1fr; }
.sl-faq-accordion .sl-a-inner { overflow: hidden; }
.sl-faq-accordion .sl-a-content { padding: 1.25rem 1.5rem 1.5rem; color: var(--smartlearn-text-muted); line-height: 1.7; border-top: 1px solid var(--smartlearn-card-border, rgba(148, 163, 184, 0.25)); }
.sl-faq-accordion .sl-a-content p { margin: 0; }
@media (prefers-reduced-motion: reduce) { .sl-faq-accordion .sl-q-btn::after, .sl-faq-accordion .sl-a-wrapper { transition: none; } }

