(function() {
  var init = function() {
    document.querySelectorAll('.sl-faq-accordion').forEach(function(section, sIdx) {
      if (section.dataset.slInit === '1') return;
      section.dataset.slInit = '1';
      var uid = 'sl-faq-acc-' + sIdx + '-' + Math.random().toString(36).slice(2, 7);
      var items = section.querySelectorAll('.sl-item');
      items.forEach(function(item, iIdx) {
        var btn = item.querySelector('.sl-q-btn');
        var wrapper = item.querySelector('.sl-a-wrapper');
        if (!btn || !wrapper) return;
        var btnId = uid + '-btn-' + iIdx;
        var panelId = uid + '-panel-' + iIdx;
        btn.id = btnId;
        wrapper.id = panelId;
        btn.setAttribute('aria-controls', panelId);
        wrapper.setAttribute('aria-labelledby', btnId);
        var isOpen = item.classList.contains('active');
        btn.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
        wrapper.inert = !isOpen;
        btn.addEventListener('click', function() {
          var wasActive = item.classList.contains('active');
          items.forEach(function(other) {
            other.classList.remove('active');
            var ob = other.querySelector('.sl-q-btn');
            var ow = other.querySelector('.sl-a-wrapper');
            if (ob) ob.setAttribute('aria-expanded', 'false');
            if (ow) ow.inert = true;
          });
          if (!wasActive) {
            item.classList.add('active');
            btn.setAttribute('aria-expanded', 'true');
            wrapper.inert = false;
          }
        });
      });
    });
  };
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
